/** Python's float modulo: the result takes the divisor's sign. Zero is +0. */
function pythonModulo(left, right) {
  let remainder = left % right;
  if (remainder !== 0 && (right < 0) !== (remainder < 0)) remainder += right;
  return remainder === 0 ? 0 : remainder;
}

