const { evaluate, ExprError } = require('./src/index');
const ok = (src, want, vars) => {
  const got = evaluate(src, vars);
  console.log(Object.is(got, want) ? 'ok  ' : 'FAIL', JSON.stringify(src), got);
};
const err = (src, col, vars) => {
  try { evaluate(src, vars); console.log('FAIL no error', src); }
  catch (e) { console.log(e instanceof ExprError && e.column === col ? 'ok  ' : 'FAIL', JSON.stringify(src), e.message, e.column); }
};
ok('-2 ** 2', -4); ok('2 ** -1', 0.5); ok('2 ** 3 ** 2', 512); ok('-7 // 2', -4);
ok('-7 % 3', 2); ok('7 % -3', -2); ok('-6 % 3', 0); ok('-0.0 // 5', 0); ok('7.5 // 2', 3);
ok('1 < 3 < 2', false); ok('1 < 2 <= 2', true); ok('(1 < 2) + 1', 2); ok('(1<2) == 1', true);
ok('max(1 < 2, 0)', true); ok('min(0, -0.0)', 0); ok('abs(-3)', 3); ok('1.5e-3 * 1000', 1.5);
ok('.5 + 5.', 5.5); ok('- - 3', 3); ok('2 * -3 ** 2', -18);
err('1 +', 4); err('1 +  ', 6); err('  1 $', 5); err('foo(1)', 1); err('  abs(1, 2)', 3);
err('min()', 1); err('1 / 0', 3); err('1 // (1 < 0)', 3); err('a + b', 5, { a: 1 });
err('min(1,)', 7); err('2 (3)', 3);
let reads = 0;
const vars = { get x() { reads += 1; return 2; } };
ok('1 < x < 3', true, vars); console.log(reads === 1 ? 'ok   getter once' : 'FAIL getter');
let calls = 0;
ok('3 < 1 < y', false, { get y() { calls += 1; return 0; } }); console.log(calls === 0 ? 'ok   short-circuit' : 'FAIL');
const n = 200000;
for (const [label, src] of [['sum', Array(n).fill('1').join(' + ')], ['cmp', Array(n).fill('1').join(' <= ')], ['signs', '-'.repeat(n) + '1']]) {
  const t = Date.now(); const v = evaluate(src); console.log(label, v, Date.now() - t, 'ms');
}
